    },
    "spec": {
      "type": "string",
      "description": "The specification of the placeholder function."
    },
    "input_schema": {
      "type": "object",
      "properties": {
        "type": {
          "const": "object"
        },
        "description": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "The description of the object input."
        },
        "properties": {
          "type": "object",
          "additionalProperties": {
            "$ref": "InputSchema"
          },
          "description": "The properties of the object input."
        },
        "required": {
          "anyOf": [
            {
              "type": "array",
              "items": {
                "type": "string"
              }
